// trial and error; this is that loop's reading side as text.
import { walkReport, floorPlan } from "./rooms.mjs";
import { lightField, lightMaps } from "./light.mjs";

const strip = (n) => String(n).replace(/^minecraft:/, "");
const PASS = /air$|carpet|pressure_plate|torch|_button|lever|flower$|tulip|grass$|fern$|sapling|snow$|vine|ladder|_sign$|banner$|candle$|light$|_door$|fence_gate$|bush$|poppy|dandelion|orchid|allium|bluet|daisy|cornflower|lily_of|azalea$|moss_carpet|rail$|redstone_wire/;

/** Lantern spots (at most `most`) that lift the room's floor cells below level 8, best first: hanging from the ceiling
 * where the room is 3+ high (out of the way), else on the floor against a wall. Greedy, by cells lifted to 8+. */
export function suggestLights(grid, box, { most = 3 } = {}) {
  const [x0, y0, z0, x1, y1, z1] = box;
  const pass = (x, y, z) => !grid.inBounds(x, y, z) || PASS.test(strip(grid.blockAt(x, y, z)));
  const floor = [];
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++)
    for (let y = y0; y <= y1; y++) if (pass(x, y, z) && pass(x, y + 1, z) && grid.inBounds(x, y - 1, z) && !pass(x, y - 1, z)) { floor.push([x, y, z]); break; }
  const cands = [];
  for (const [x, y, z] of floor) {
    let top = y + 1;
    while (top + 1 <= y1 + 1 && grid.inBounds(x, top + 1, z) && grid.isAir(x, top + 1, z)) top++;
    if (top >= y + 2 && grid.inBounds(x, top + 1, z) && !grid.isAir(x, top + 1, z)) cands.push({ at: [x, top, z], how: "hanging lantern (lantern[hanging=true]) under the ceiling" });
    const wall = [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([dx, dz]) => grid.inBounds(x + dx, y, z + dz) && !pass(x + dx, y, z + dz));
    if (wall) cands.push({ at: [x, y, z], how: "lantern on the floor against the wall" });
  }
  const lowCells = (F) => floor.filter(([x, y, z]) => F.level(x, y, z) < 8).length;
  let base = lowCells(lightField(grid));
  const picks = [];
  while (picks.length < most && base > 0 && cands.length) {
    let best = null;
    for (const c of cands) {
      const [x, y, z] = c.at, was = grid.get(x, y, z);
      grid.set(x, y, z, "minecraft:lantern", c.how.startsWith("hanging") ? { hanging: "true" } : undefined);
      const left = lowCells(lightField(grid));
      if (was) grid.set(x, y, z, was.block, was.state, was.nbt); else grid.unset(x, y, z);
      if (!best || left < best.left) best = { ...c, left };
    }
    if (!best || best.left >= base) break;
    picks.push({ ...best, lifts: base - best.left });
    const [x, y, z] = best.at;
    grid.set(x, y, z, "minecraft:lantern", best.how.startsWith("hanging") ? { hanging: "true" } : undefined);   // keep it for the next pick
    base = best.left;
    cands.splice(cands.findIndex((c) => c.at === best.at), 1);
  }
  for (const p of picks) grid.unset(...p.at);
  return picks;
}

